let amplitude = Number(msg.payload.Amplitude);
let offset = Number(msg.payload.Offset);

msg.ui_update = {
        min: offset - amplitude,
        max: offset + amplitude
};

msg.payload = 0;

return msg;

/*################################# 
    Init Variables
#################################*/
let nameIDMap = global.get("NameIDMap");      //global defined in "Name - ID zuordenen"
let idValueMap = global.get("IDValueMap");    //global defined in "Name - ID zuordenen", changed here with every message
let oldValues = global.get("oldValues");      //global defined in "Name - ID zuordenen", changed here when parameters changed

//Variables for writing changes of the parameters to the form
let iterator = idValueMap.keys()
let id;
let changed = false;
let variableName="sinusVal";

/*################################# 
    Check if a parameter changed
#################################*/
idValueMap.forEach( () => {
    id = iterator.next().value;
    if(id != nameIDMap.get(variableName))
    {
        if(idValueMap.get(id) != oldValues.get(id))
        {
            oldValues.set(id, idValueMap.get(id));
            changed = true;
        }
    }
})

/*################################# 
   if changed- update parameters in the form
#################################*/
if(changed)
{
    changed = false;
    msg.payload = 
    {
        "Frequency": idValueMap.get(nameIDMap.get("Frequency")).toFixed(2),
        "Amplitude": idValueMap.get(nameIDMap.get("Amplitude")).toFixed(1),
        "Offset": idValueMap.get(nameIDMap.get("Offset")).toFixed(1)
    }
}else 
{
    msg = null;
}

/*################################# 
    update global maps
#################################*/ 
global.set("oldValues", oldValues);

return msg;

